// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner1, address newOwner2) public {
        vm.assume(newOwner1 != address(0));
        vm.assume(newOwner2 != address(0));
        vm.prank(address(0));
        c.transferOwnership(newOwner1);
        vm.prank(newOwner1);
        c.transferOwnership(newOwner2);
        vm.prank(newOwner2);
        c.owned();
        assertTrue(c.owner() != address(0));
    }
}

